# -*- coding: utf-8 -*-
"""工作流 REST API + 画布页面。路由前缀 /api/workflow-plus;页面路由 /workflow-plus/page。"""
from __future__ import annotations
from typing import Any, Optional
from fastapi import APIRouter, Body, HTTPException
from fastapi.responses import HTMLResponse, JSONResponse
from pydantic import BaseModel
from . import engine, store

api_router = APIRouter()
page_router = APIRouter()

class WorkflowBody(BaseModel):
    id: Optional[str] = None
    name: str = ""
    profile: str = "default"
    workspace: Optional[str] = None
    nodes: list = []
    edges: list = []
    viewport: dict = {}

class BatchDeleteBody(BaseModel):
    ids: list[str]

@api_router.get("/workflow-plus/workflows")
async def list_workflows(profile: Optional[str] = None):
    return {"workflows": store.list_workflows(profile)}

@api_router.post("/workflow-plus/workflows")
async def create_workflow(body: WorkflowBody = Body(...)):
    return store.save_workflow(body.model_dump(), create=True)

@api_router.get("/workflow-plus/workflows/{wf_id}")
async def get_workflow(wf_id: str):
    d = store.get_workflow(wf_id)
    if not d: raise HTTPException(404, "workflow not found")
    return d

@api_router.patch("/workflow-plus/workflows/{wf_id}")
async def patch_workflow(wf_id: str, body: dict = Body(...)):
    d = store.get_workflow(wf_id)
    if not d: raise HTTPException(404, "workflow not found")
    errs = engine.validate_graph(body.get("nodes", d["nodes"]), body.get("edges", d["edges"]))
    if errs: return JSONResponse({"errors": errs}, status_code=422)
    d.update({k: body[k] for k in ("name", "profile", "workspace", "nodes", "edges", "viewport") if k in body})
    return store.save_workflow(d)

@api_router.post("/workflow-plus/workflows/batch-delete")
async def batch_delete(body: BatchDeleteBody = Body(...)):
    return {"deleted": store.delete_workflows(body.ids)}

@api_router.delete("/workflow-plus/workflows/{wf_id}")
async def delete_workflow(wf_id: str):
    return {"deleted": store.delete_workflows([wf_id])}

@api_router.post("/workflow-plus/workflows/{wf_id}/run")
async def run_workflow(wf_id: str):
    run_id = await engine.run_workflow(wf_id)
    if run_id is None: raise HTTPException(404, "workflow not found")
    return {"run_id": run_id}

@api_router.get("/workflow-plus/runs/{run_id}")
async def get_run(run_id: str):
    d = store.get_run(run_id)
    if not d: raise HTTPException(404, "run not found")
    return d

@api_router.get("/workflow-plus/workflows/{wf_id}/runs")
async def list_runs(wf_id: str):
    return {"runs": []}

@api_router.get("/workflow-plus/agents")
async def list_agents():
    import asyncio as _aio
    from ..agents.tools.agent_management import list_agents_data
    try:
        data = await _aio.wait_for(_aio.to_thread(list_agents_data), 15)
        items = data if isinstance(data, list) else (data or {}).get("agents", [])
        return {"agents": [{"id": a.get("id"), "name": a.get("name", a.get("id"))} for a in items]}
    except Exception as exc:
        return {"agents": [], "error": str(exc)[:200]}

@page_router.get("/workflow-plus/page", response_class=HTMLResponse)
async def workflow_page():
    from .page import PAGE_HTML
    return HTMLResponse(PAGE_HTML, headers={"Cache-Control": "no-cache, no-store, must-revalidate, max-age=0"})
